pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function name() external view returns (string memory);
    function symbol() external view returns (string memory);
    function decimals() external view returns (uint8);
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
}

interface ShibaMoon is IERC20 {}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xf7958ffc6cE46dE09e0AB69B7dA360C38b16266B;
    address attacker = address(this);
    ShibaMoon target;
    IERC20 token;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = ShibaMoon(payable(TARGET));
        vm.label(TARGET, "ShibaMoon Contract");
        vm.label(attacker, "Attacker");
        // Inject some BNB for gas
        deal(attacker, 1 ether);
        // Get token balance for testing
        token = IERC20(TARGET);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Floating Pragma is a code quality issue, not runtime exploitable
        // This test demonstrates the contract is accessible despite the issue

        // Verify contract is deployed and accessible via interface
        IERC20 token = IERC20(TARGET);

        // Basic state checks - these should work without timeout
        string memory name = token.name();
        assertEq(name, "ShibaMoon", "Name should match");

        string memory symbol = token.symbol();
        assertEq(symbol, "SHIBAMOON", "Symbol should match");

        uint8 decimals = token.decimals();
        assertEq(decimals, 8, "Decimals should be 8");

        // Verify total supply exists
        uint256 totalSupply = token.totalSupply();
        assertGt(totalSupply, 0, "Total supply should be greater than 0");

        // The "vulnerability" is that pragma solidity ^0.6.12 allows multiple compiler versions
        // Fix: Change to pragma solidity 0.6.12; for reproducible builds
        // This cannot be exploited post-deployment as bytecode is immutable

        emit log("Floating Pragma: Code quality issue - requires source code fix");
        emit log("Cannot be exploited post-deployment");
        emit log("Contract is functional despite floating pragma");
    }




    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

